record.field:
action = False
for rec in records.sudo():
    attachment = False
    if rec.x_source_attachment_id:
        attachment = rec.x_source_attachment_id
    elif 'x_attachment_id' in rec._fields and rec.x_attachment_id:
        attachment = rec.x_attachment_id

    if attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Download Source Attachment',
                'message': 'No source attachment is linked to this identification record.',
                'type': 'warning',
                'sticky': False,
            }
        }
